@RestController
@RequestMapping("/api/orders")
public class OrderAsyncController {

    private final OrderService orderService;
    private final ThreadPoolTaskExecutor taskExecutor;

    public OrderAsyncController(OrderService orderService, ThreadPoolTaskExecutor taskExecutor) {
        this.orderService = orderService;
        this.taskExecutor = taskExecutor;
    }

    @GetMapping("/{id}/callable")
    public Callable<ResponseEntity<Order>> getOrderCallable(@PathVariable Long id) {
        return () -> {
            Order order = orderService.fetchHeavyOrderDetails(id);
            return ResponseEntity.ok(order);
        };
    }

    @GetMapping("/{id}/deferred")
    public DeferredResult<ResponseEntity<Order>> getOrderDeferred(@PathVariable Long id) {
        DeferredResult<ResponseEntity<Order>> deferredResult = new DeferredResult<>(5000L);

        deferredResult.onTimeout(() -> 
            deferredResult.setResult(ResponseEntity.status(HttpStatus.REQUEST_TIMEOUT).build())
        );

        taskExecutor.execute(() -> {
            try {
                Order order = orderService.fetchHeavyOrderDetails(id);
                deferredResult.setResult(ResponseEntity.ok(order));
            } catch (Exception e) {
                deferredResult.setErrorResult(ResponseEntity.internalServerError().build());
            }
        });

        return deferredResult;
    }

    @GetMapping("/{id}/web-async")
    public WebAsyncTask<ResponseEntity<Order>> getOrderWebAsyncTask(@PathVariable Long id) {
        Callable<ResponseEntity<Order>> task = () -> {
            Order order = orderService.fetchHeavyOrderDetails(id);
            return ResponseEntity.ok(order);
        };

        WebAsyncTask<ResponseEntity<Order>> webAsyncTask = new WebAsyncTask<>(3000L, task);
        webAsyncTask.setTaskExecutor(taskExecutor);
        webAsyncTask.onTimeout(() -> ResponseEntity.status(HttpStatus.GATEWAY_TIMEOUT).build());
        return webAsyncTask;
    }
}
